model.p.fct_siparis.raw_code:
select * from {{ ref('stg_siparis') }}
{% if is_incremental() %}
where guncelleme >= (select max(guncelleme) - interval '3 day' from {{ this }})
{% endif %}

model.p.fct_olay.raw_code:
select * from {{ ref('stg_olay') }}
{% if is_incremental() %}
where olay_zamani > (select max(olay_zamani) from {{ this }})
{% endif %}

model.p.fct_log.raw_code:
select * from {{ source('app', 'log') }}
{% if is_incremental() %}
where ts > (select dateadd(day, -1, max(ts)) from {{ this }})
{% endif %}
